-- Table structure for articles_cache
-- ----------------------------
DROP TABLE IF EXISTS `articles_cache`;
CREATE TABLE `articles_cache`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PubMed PMID',
  `doi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '英文标题',
  `title_zh` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '中文标题',
  `abstract` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '英文摘要',
  `abstract_zh` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '中文摘要',
  `authors` json NULL COMMENT '作者列表',
  `publication_date` date NULL DEFAULT NULL COMMENT '发布日期',
  `journal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '期刊名',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原文链接',
  `tags` json NULL COMMENT '文章类型标签',
  `sub_tags` json NULL COMMENT '标签细分',
  `impact_factor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '影响因子(IF)',
  `research_stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '研究阶段',
  `ai_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'AI一句话总结',
  `full_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文章原文内容',
  `content_fetched_at` timestamp NULL DEFAULT NULL COMMENT '原文抓取时间',
  `fetched_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '抓取时间',
  `view_count` int UNSIGNED NULL DEFAULT 0 COMMENT '浏览量',
  `created_by_user_id` int NULL DEFAULT NULL COMMENT '创建者用户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_articles_doi`(`doi` ASC) USING BTREE,
  INDEX `idx_publication_date`(`publication_date` ASC) USING BTREE,
  INDEX `idx_fetched_at`(`fetched_at` ASC) USING BTREE,
  INDEX `idx_pub_date_fetched`(`publication_date` ASC, `fetched_at` DESC) USING BTREE,
  INDEX `idx_view_count`(`view_count` DESC) USING BTREE,
  INDEX `idx_created_by_user`(`created_by_user_id` ASC) USING BTREE,
  INDEX `idx_created_by_fetched`(`created_by_user_id` ASC, `fetched_at` DESC) USING BTREE,
  INDEX `idx_pub_date_id`(`publication_date` DESC, `id` ASC) USING BTREE,
  FULLTEXT INDEX `ft_search`(`title`, `title_zh`, `abstract`, `abstract_zh`)
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '文章缓存表' ROW_FORMAT = DYNAMIC;

