-- Table structure for email_push_logs
-- ----------------------------
DROP TABLE IF EXISTS `email_push_logs`;
CREATE TABLE `email_push_logs`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `article_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文章ID (PubMed PMID)',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '推送邮箱',
  `status` enum('success','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'success' COMMENT '推送状态',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误信息',
  `pushed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '推送时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_article`(`user_id` ASC, `article_id` ASC) USING BTREE COMMENT '同一用户同一文章只推送一次',
  INDEX `idx_pushed_at`(`pushed_at` ASC) USING BTREE,
  INDEX `idx_status_pushed_at`(`status` ASC, `pushed_at` ASC) USING BTREE,
  INDEX `idx_user_pushed_at`(`user_id` ASC, `pushed_at` DESC) USING BTREE,
  CONSTRAINT `email_push_logs_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1157 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '邮件推送记录表' ROW_FORMAT = DYNAMIC;

