-- ----------------------------
-- Table structure for rehab_checkins
-- ----------------------------
DROP TABLE IF EXISTS `rehab_checkins`;
CREATE TABLE `rehab_checkins`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '关联用户ID',
  `assessment_id` bigint NULL DEFAULT NULL COMMENT '关联评估ID',
  `duration_plan` int NOT NULL COMMENT '计划时长(分钟): 10 或 20',
  `video_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '跟练视频分组(level1/level2/level3)',
  `video_count` int NOT NULL COMMENT '计划视频数量',
  `completed_count` int NOT NULL DEFAULT 0 COMMENT '实际完成视频数量',
  `is_completed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否完成全部训练',
  `checkin_date` date NOT NULL COMMENT '打卡日期',
  `started_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始训练时间',
  `completed_at` timestamp NULL DEFAULT NULL COMMENT '完成训练时间',
  `duration_actual` int NULL DEFAULT NULL COMMENT '实际训练时长(秒)',
  `next_reminder_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预约次日提醒时间(HH:mm)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_checkin_date`(`checkin_date` ASC) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `checkin_date` DESC) USING BTREE,
  INDEX `rehab_checkins_ibfk_2`(`assessment_id` ASC) USING BTREE,
  INDEX `idx_video_group`(`video_group` ASC) USING BTREE,
  INDEX `idx_user_completed_group_date`(`user_id` ASC, `is_completed` ASC, `video_group` ASC, `checkin_date` DESC, `started_at` DESC) USING BTREE,
  INDEX `idx_user_completed_date`(`user_id` ASC, `is_completed` ASC, `checkin_date` DESC, `id` DESC) USING BTREE,
  INDEX `idx_user_date_completed`(`user_id` ASC, `checkin_date` ASC, `is_completed` ASC, `id` DESC) USING BTREE,
  CONSTRAINT `rehab_checkins_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rehab_checkins_ibfk_2` FOREIGN KEY (`assessment_id`) REFERENCES `rehab_assessments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 224 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '康复打卡记录表' ROW_FORMAT = DYNAMIC;

