  INDEX `idx_article_id`(`article_id` ASC) USING BTREE,
  INDEX `idx_inquiry_date`(`inquiry_date` ASC) USING BTREE,
  INDEX `idx_user_inquiry_date`(`user_id` ASC, `inquiry_date` DESC) USING BTREE,
  CONSTRAINT `saved_inquiries_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '保存的查询表' ROW_FORMAT = DYNAMIC;

