-- Records of wechat_users
-- ----------------------------

-- ----------------------------
-- View structure for v_user_interests_summary
-- ----------------------------
DROP VIEW IF EXISTS `v_user_interests_summary`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_user_interests_summary` AS select `u`.`id` AS `user_id`,`u`.`username` AS `username`,group_concat(`ui`.`interest_area` separator ',') AS `interests` from (`users` `u` left join `user_interests` `ui` on((`u`.`id` = `ui`.`user_id`))) group by `u`.`id`,`u`.`username`;

SET FOREIGN_KEY_CHECKS = 1;
